#include <functional>
#include <iostream>
#include <string>
#include <vector>

struct TestCase
{
    std::string name{};
    std::function<void()> body{};
};

std::vector<TestCase>& registry()
{
    static std::vector<TestCase> tests{};
    return tests;
}

int main()
{
    std::cout << registry().size() << " tests\n";
}
